import { useEffect, useState } from 'react';
import axios from 'axios';

export default function Leaderboard() {
  const [leaderboard, setLeaderboard] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/quizzes/leaderboard')
      .then(res => setLeaderboard(res.data));
  }, []);

  return (
    <div className="p-6">
      <h1 className="text-2xl mb-4">Leaderboard</h1>
      <table className="min-w-full border">
        <thead>
          <tr>
            <th className="border p-2">Rank</th>
            <th className="border p-2">User</th>
            <th className="border p-2">Score (%)</th>
            <th className="border p-2">Time (s)</th>
          </tr>
        </thead>
        <tbody>
          {leaderboard.map((entry, idx) => (
            <tr key={entry._id}>
              <td className="border p-2">{idx + 1}</td>
              <td className="border p-2">{entry.user.name}</td>
              <td className="border p-2">{entry.score}</td>
              <td className="border p-2">{entry.totalTimeTaken}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
